package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen2Test {





















    @Test
    public void testRandom_SurrogateHandling_HighSurrogate() {
        // High surrogate range: 55296 to 56191
        // We force the random to pick a high surrogate by providing a custom Random
        Random fixedRandom = new Random() {
            @Override
            public int nextInt(int bound) {
                // Force the selection of the high surrogate index
                // We need to ensure (nextInt(gap) + start) lands in the high surrogate range
                // Let's use a char array containing a high surrogate
                return 0;
            }
        };
        char[] surrogates = {(char) 55296, 'a'};
        // Gap is 2. nextInt(2) returns 0 or 1.
        // If it returns 0, it picks 55296.
        // The code handles high surrogate by inserting a low surrogate (56320 + rand) before it.
        String result = RandomStringUtils.random(2, 0, 2, false, false, surrogates, fixedRandom);
        assertNotNull(result);
    }






}

