public class RandomStringUtils_random_TriageGen2Test {

























    @Test
    public void testRandom_SurrogateHandling_PrivateHighSurrogate() {
        // Private high surrogate range: 56192 to 56319 (should be skipped)
        char[] surrogates = {(char) 56200, 'a'};
        Random fixedRandom = new Random() {
            @Override
            public int nextInt(int bound) {
                return 0;
            }
        };
        // Since it skips, it should eventually pick 'a' to satisfy count
        String result = RandomStringUtils.random(1, 0, 2, false, false, surrogates, fixedRandom);
        assertEquals("a", result);
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen2Test {



























    @Test
    public void testRandom_FilteredCharacters() {
        // If letters=true, numbers=false, and random picks a digit, it should skip and increment count
        char[] mixed = {'1', 'a'};
        Random fixedRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                // First call returns 0 (digit '1'), second call returns 1 (letter 'a')
                return (callCount == 1) ? 0 : 1;
            }
        };
        String result = RandomStringUtils.random(1, 0, 2, true, false, mixed, fixedRandom);
        assertEquals("a", result);
    }
}
